import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.DdtnLau3.js";const h=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function o(s,e,d,p,l,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>One Linux application provides <strong>Core</strong>, the web workbench, <strong>Admin</strong> and first-time setup. Open the server IP from a Linux or Windows browser; the independent CLI is optional.</p><ol><li><a href="/piwork/guide/quick-start.html">Start with one command</a>: run one Docker container, create an administrator with password confirmation through the private setup link, then sign in and configure a model in <strong>Admin → Quick setup</strong>.</li><li><a href="/piwork/guide/installation.html">Installation and Deployment</a>: platforms, ports, persistence, optional Compose, troubleshooting and recovery.</li><li><a href="/piwork/guide/first-work.html">Your First Work</a>: wait for preparation, select <strong>Open workbench</strong>, then create a Work and use Chat, Files and Services.</li></ol><p>For an existing installation, open the workbench directly. Administrators return through <strong>Overview → Quick setup</strong>. <strong>Save and continue</strong> saves the model and binds CoreRuntime in sequence. Test is explicit and optional; the server release fixes the Agent image without an image field.</p><p>Building an application? <a href="/piwork/guide/web-development.html">Web Development</a> covers the default environment, persistence and upgrades. See <a href="/piwork/guide/ai-models.html">AI Models</a> for protocols, Keys, Test and Thinking.</p><h2 id="current-scope" tabindex="-1">Current scope <a class="header-anchor" href="#current-scope" aria-label="Permalink to &quot;Current scope&quot;">​</a></h2><p>Images target Linux amd64. Core uses rootful Docker Engine 28+ and its local Unix socket. Remote browsers need no domain, DNS, WSL or client CLI. The main port is 7171, Service entries use 17891–17954, and 7172 is internal Agent RPC. Compose 2.24+ is needed only for optional Compose deployment.</p><p>The <a href="/piwork/spec/">Spec overview</a> records source and image provenance. For an application example, see <a href="/piwork/demo/kanban.html">Kanban Work</a>.</p><p><a href="/piwork/guide/quick-start.html">Quick Start</a> uses the unified application and browser onboarding. CLI is optional; native builds and administrator operations have separate navigation.</p>',9)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
